#[test]
fn cd_permission_denied_folder() {
    Playground::setup("cd_test_21", |dirs, sandbox| {
        sandbox.mkdir("banned");
        let actual = nu!(
            cwd: dirs.test(),
            "
                chmod -x banned
                cd banned
            "
        );
        assert!(actual.err.contains("Cannot change directory to"));
        nu!(
            cwd: dirs.test(),
            "
                chmod +x banned
                rm banned
            "
        );
    });
}
